INSERT INTO exercise (id, name, muscle_group, description) VALUES
('0fa2b819-38d4-4e88-aa18-3d406579158b', 'Supino Inclinado', 'CHEST', 'Igual ao supino reto, mas com o banco inclinado para focar na parte superior do peito.'),
('0a422278-9a04-4de0-9437-877acbfafb94', 'Crucifixo', 'CHEST', 'Deitado, abra e feche os braços com halteres em movimento de arco, mantendo leve flexão nos cotovelos.'),
('d2e3bd33-50e4-4aad-950a-0232e10ed31b', 'Puxada Frontal', 'LATS', 'Sentado na polia alta, puxe a barra até a altura do queixo, contraindo as costas.'),
('72c84c54-6d01-43a5-ae4c-c34e5cc2cbd7', 'Remada Curvada', 'LATS', 'Com o tronco inclinado à frente, puxe a barra em direção ao abdômen.'),
('8ae772f1-c4fa-4e36-82ae-667134e6ecca', 'Barra Fixa', 'LATS', 'Pendurado na barra, puxe o corpo para cima até o queixo passar da barra.'),
('419793a7-f3a7-4d6e-87b1-e440a58474fe', 'Remada Cavalinho', 'MIDDLE_BACK', 'Apoiado sobre a barra em T, puxe o peso em direção ao tronco.'),
('411e9146-8e97-447f-a3e9-0fbe09902f0e', 'Remada Baixa', 'MIDDLE_BACK', 'Sentado na polia baixa, puxe o cabo em direção ao abdômen mantendo as costas retas.'),
('440db3d9-dcc2-4a8c-aace-d538677ec0af', 'Hiperextensão Lombar', 'LOWER_BACK', 'No banco romano, flexione e estenda o tronco trabalhando a lombar.'),
('77a9d137-7789-4738-9e55-42d86c76ce0b', 'Levantamento Terra', 'LOWER_BACK', 'Com a barra no chão, levante-a estendendo quadril e joelhos, mantendo as costas retas.'),
('de2b8c1a-07b5-4bf0-875d-e01e49b61adb', 'Desenvolvimento com Halteres', 'SHOULDERS', 'Sentado ou em pé, empurre os halteres para cima acima da cabeça.'),
('a4a266ba-2ad0-4f32-a98f-429fa8e52af1', 'Elevação Lateral', 'SHOULDERS', 'Com halteres nas mãos, eleve os braços lateralmente até a altura dos ombros.'),
('7172654d-0068-4acf-a036-7858fca2d754', 'Elevação Frontal', 'SHOULDERS', 'Eleve os halteres à frente do corpo até a altura dos ombros.'),
('8cef8d8c-149c-41fd-8880-fee8c8b19bf1', 'Encolhimento com Halteres', 'TRAPS', 'Com halteres ao lado do corpo, eleve os ombros em direção às orelhas.'),
('56a833f5-a83a-44ed-aa5c-679327792ddd', 'Encolhimento com Barra', 'TRAPS', 'Segurando a barra à frente do corpo, eleve os ombros em direção às orelhas.'),
('d9a06c2d-d7cc-446c-914a-eea63fc39bbd', 'Rosca Direta', 'BICEPS', 'Com a barra, flexione os cotovelos levando o peso em direção aos ombros.'),
('f988278d-4fcc-4b6e-8579-7d2a4131b71b', 'Rosca Alternada', 'BICEPS', 'Com halteres, flexione um braço de cada vez alternadamente.'),
('af962e9a-b6d5-4ab6-91e0-722fe3a29e85', 'Rosca Scott', 'BICEPS', 'Apoiado no banco Scott, flexione os cotovelos isolando o bíceps.'),
('013b5524-50ff-43ca-8636-6b69a0987d33', 'Tríceps Corda', 'TRICEPS', 'Na polia alta com a corda, estenda os cotovelos empurrando para baixo.'),
('df86c592-bd26-4873-ab02-fd725c1abeec', 'Tríceps Testa', 'TRICEPS', 'Deitado, flexione e estenda os cotovelos levando a barra em direção à testa.'),
('d2022f4f-5b60-4f4f-b0c6-72a3c1766351', 'Mergulho no Banco', 'TRICEPS', 'Apoiado em dois bancos, flexione e estenda os cotovelos abaixando o corpo.'),
('a503e4e2-14f4-46f7-8eb8-bd298ef9a80e', 'Rosca de Punho', 'FOREARMS', 'Com halteres ou barra, flexione apenas os punhos para cima.'),
('2a4b48ea-fc03-4cca-b0a8-91c910d4adaa', 'Rosca Inversa', 'FOREARMS', 'Com pegada pronada na barra, flexione os cotovelos trabalhando antebraço.'),
('e630fabb-d613-4656-a5a9-513ccef40732', 'Abdominal Supra', 'ABDOMINALS', 'Deitado, flexione o tronco em direção aos joelhos.'),
('ef12d40f-790d-4c50-98c1-99b8c18f8121', 'Prancha', 'ABDOMINALS', 'Apoiado nos antebraços e pés, mantenha o corpo reto e estático.'),
('3389b21e-b771-4aed-9a22-9d5cdea35e79', 'Abdominal Infra', 'ABDOMINALS', 'Deitado, eleve as pernas em direção ao tronco.'),
('576b5d23-0d89-43a9-a504-f3fef55a6b37', 'Agachamento Livre', 'QUADRICEPS', 'Com a barra nas costas, flexione os joelhos descendo o quadril.'),
('922a036a-9e37-4c66-a70b-c77d186e034d', 'Leg Press', 'QUADRICEPS', 'Sentado no aparelho, empurre a plataforma estendendo as pernas.'),
('1448ffcf-8580-4a70-9fbf-a385d52c05c2', 'Cadeira Extensora', 'QUADRICEPS', 'Sentado, estenda os joelhos elevando o peso.'),
('92db6c4d-292a-4476-9a69-f40164870b2c', 'Cadeira Flexora', 'HAMSTRINGS', 'Deitado ou sentado, flexione os joelhos trazendo o peso em direção ao glúteo.'),
('1ac314e5-714e-4cb3-9071-f6eb3b0f0dce', 'Stiff', 'HAMSTRINGS', 'Com a barra, incline o tronco à frente mantendo as pernas quase retas.'),
('32a7f795-6c6d-404d-ac3b-31569d09f27c', 'Elevação Pélvica', 'GLUTES', 'Deitado, eleve o quadril contraindo o glúteo.'),
('684aef63-e8e0-44ac-87e5-8317513c6d57', 'Coice na Polia', 'GLUTES', 'Na polia baixa, estenda a perna para trás contraindo o glúteo.'),
('b649a787-88e2-41d0-acf9-e281b967a5f1', 'Cadeira Abdutora', 'ABDUCTORS', 'Sentado, afaste as pernas contra a resistência do aparelho.'),
('9bf1952c-27cf-43e8-b395-53cbe3181050', 'Elevação Lateral de Perna', 'ABDUCTORS', 'Deitado de lado, eleve a perna de cima lateralmente.'),
('dd0ff491-fdb3-4ff2-9897-889428796707', 'Supino Reto', 'CHEST', 'Deitado no banco reto, empurre a barra ou halteres para cima até estender os braços.'),
('91d7faee-ec26-4a92-96ee-e5996c399878', 'Cadeira Adutora', 'ADDUCTORS', 'Sentado, aproxime as pernas contra a resistência do aparelho.'),
('1e2a3c64-4e2a-4666-b6e9-7f56a973016e', 'Elevação de Perna Cruzada', 'ADDUCTORS', 'Deitado, cruze a perna sobre o corpo trabalhando a parte interna da coxa.'),
('b4ea901c-3bb1-479a-a588-59a1b30768ef', 'Elevação de Panturrilha em Pé', 'CALVES', 'Em pé, eleve os calcanhares ficando na ponta dos pés.'),
('471e7c46-82d2-4542-99a3-9b8556835380', 'Elevação de Panturrilha Sentado', 'CALVES', 'Sentado, eleve os calcanhares com peso apoiado sobre os joelhos.'),
('7543f863-7676-43ae-9ae2-c9b770538e49', 'Flexão de Pescoço', 'NECK', 'Deitado, flexione o pescoço levando o queixo em direção ao peito.'),
('36c80672-512f-4027-88cc-4c5d39b6d54e', 'Extensão de Pescoço', 'NECK', 'Deitado de bruços, estenda o pescoço levando a cabeça para trás.'),
('a1daea73-4b26-453f-9efb-a60822dfb5d0', 'Crucifixo na polia', 'CHEST', 'Fique no centro das polias, mantenha os braços levemente flexionados e junte as mãos à frente do corpo, contraindo o peito. Retorne devagar à posição inicial.'),
('f700b125-0205-4832-9651-7df7ae1de79a', 'Supino Declinado', 'CHEST', 'Deitado no banco declinado, empurre a barra ou halteres para cima focando na porção inferior do peito.'),
('19d75a72-94da-4d3c-bf4f-ea708e633128', 'Peck Deck', 'CHEST', 'Sentado no aparelho, aproxime os braços à frente do corpo contraindo o peitoral.'),
('ad3288a5-aaa0-4e1a-8f5c-fb93aa1cf5d7', 'Flexão de Braço', 'CHEST', 'Apoiado nas mãos e pés, flexione e estenda os cotovelos abaixando e subindo o corpo.'),
('26f93e54-9ed2-4f15-a99f-5896899f4aca', 'Crossover na Polia', 'CHEST', 'Em pé entre as polias altas, puxe os cabos para frente e para baixo cruzando à frente do corpo.'),
('d848bba4-8445-4dfb-be48-7880e92a0766', 'Supino Máquina', 'CHEST', 'Sentado no aparelho, empurre as alavancas à frente estendendo os braços.'),
('828158e2-40a8-4556-adf9-7771afee2f4a', 'Puxada Aberta', 'LATS', 'Na polia alta, puxe a barra com pegada aberta até a altura do peito.'),
('f77cbcb2-afea-4c67-aed3-f9e529dbee15', 'Remada Unilateral', 'LATS', 'Apoiado no banco com um joelho e uma mão, puxe o halter até a altura do quadril.'),
('82a4cfd8-70ed-4d23-b88d-a6898088f769', 'Pullover', 'LATS', 'Deitado no banco, leve o halter de trás da cabeça até acima do peito com os braços semiestendidos.'),
('20fa70af-136c-4b67-8eeb-7fa2a74c9f38', 'Puxada Triângulo', 'LATS', 'Na polia alta com o triângulo, puxe o cabo até o peito mantendo os cotovelos próximos ao corpo.'),
('d744a64f-7913-459c-9d53-a8eadeeea70b', 'Remada Serrote', 'LATS', 'Apoiado com um joelho e uma mão no banco, puxe o halter em linha reta até a altura do quadril.'),
('55f674e7-ffd0-4058-9994-13cac0ecc984', 'Face Pull', 'MIDDLE_BACK', 'Na polia alta com corda, puxe em direção ao rosto separando as mãos no fim do movimento.'),
('403e809b-dbf0-4d61-8ddc-8c6047b4449a', 'Remada T', 'MIDDLE_BACK', 'Apoiado sobre a barra em T, puxe o peso em direção ao tronco contraindo as costas.'),
('6e33ceef-b91d-44f9-a87f-18b9a66960b6', 'Remada Máquina', 'MIDDLE_BACK', 'Sentado no aparelho com o peito apoiado, puxe as alavancas em direção ao tronco.'),
('442e0e0d-acd4-4eee-922b-8ea37d26a4c0', 'Puxada Horizontal com Barra', 'MIDDLE_BACK', 'Sentado na polia baixa com barra reta, puxe em direção ao abdômen contraindo as escápulas.'),
('9c637bf2-3737-4fb5-b59f-b8f23dd341d6', 'Bom Dia', 'LOWER_BACK', 'Com a barra apoiada nas costas, incline o tronco à frente mantendo os joelhos levemente flexionados.'),
('949d888c-4049-49ba-8cd6-5a9b539fce6f', 'Extensão de Tronco no Solo', 'LOWER_BACK', 'Deitado de bruços, eleve o tronco contraindo a lombar e retorne.'),
('0f9b0620-aac2-4858-9035-20aee0826a64', 'Superman', 'LOWER_BACK', 'Deitado de bruços, eleve simultaneamente braços e pernas contraindo a lombar.'),
('530c4e7c-afbe-40ee-95cb-f0882e016dc0', 'Levantamento Terra Romeno', 'LOWER_BACK', 'Com a barra à frente do corpo, incline o tronco levando o peso próximo às pernas com joelhos levemente flexionados.'),
('1ec9900e-c130-400c-9459-4dff7fd7f199', 'Desenvolvimento Militar', 'SHOULDERS', 'Em pé, empurre a barra para cima a partir dos ombros até a extensão total dos braços.'),
('751d6ed4-04dc-402c-bb19-7c30bf56b256', 'Remada Alta', 'SHOULDERS', 'Em pé, puxe a barra verticalmente até a altura do peito, cotovelos acima das mãos.'),
('8e317cd4-9f21-4c51-af9d-c7137794b397', 'Desenvolvimento Arnold', 'SHOULDERS', 'Sentado, gire os halteres de pegada pronada para supinada enquanto empurra para cima.'),
('0b120a47-4914-443c-b1fd-3deea9ad3e32', 'Crucifixo Invertido', 'SHOULDERS', 'Inclinado à frente, abra os braços com halteres trabalhando a parte posterior do ombro.'),
('c8f12bd0-6cee-4be4-85f2-383e93d52bb5', 'Elevação Lateral na Polia', 'SHOULDERS', 'Na polia baixa, eleve o braço lateralmente até a altura do ombro.'),
('26e875ca-33c8-4b48-a7e0-63f36729bdf1', 'Encolhimento na Polia', 'TRAPS', 'Em pé, segurando o cabo baixo, eleve os ombros em direção às orelhas e retorne.'),
('f6866101-3ae4-48dc-8429-8fe9354dd32c', 'Encolhimento Atrás das Costas', 'TRAPS', 'Segurando a barra atrás do corpo, eleve os ombros em direção às orelhas.'),
('e60e4b97-5d66-4304-9b7f-b12e83765b4b', 'Rosca Martelo', 'BICEPS', 'Em pé, com halteres em pegada neutra, flexione os cotovelos elevando o peso.'),
('5e4d4b2b-f03a-4395-9b7f-8ac339345a12', 'Rosca Concentrada', 'BICEPS', 'Sentado, apoie o cotovelo na coxa e flexione o braço isolando o bíceps.'),
('72e0992f-80bb-4d80-8aec-e88a3666da6c', 'Rosca 21', 'BICEPS', 'Com a barra, execute 7 repetições parciais na parte baixa, 7 na parte alta e 7 completas.'),
('05786ca6-6bb7-497f-8bf7-afa8ddf84e4c', 'Rosca no Cabo', 'BICEPS', 'Na polia baixa, flexione os cotovelos puxando a barra em direção aos ombros.'),
('f8794975-4827-4a3d-a349-8ca6aef37807', 'Tríceps Francês', 'TRICEPS', 'Sentado ou em pé, segure o halter atrás da cabeça e estenda o cotovelo.'),
('9f2d2bb0-0469-4b88-b9a9-0492800316d1', 'Tríceps Coice', 'TRICEPS', 'Com o tronco inclinado à frente, estenda o cotovelo levando o halter para trás.'),
('1e1e2e1a-9ae2-486d-8fd7-d782f244e766', 'Supino Fechado', 'TRICEPS', 'Deitado, empurre a barra com pegada fechada focando o tríceps.'),
('efe366b3-0b9f-4361-a884-2475252cd645', 'Tríceps Polia Invertida', 'TRICEPS', 'Na polia alta com pegada supinada, estenda os cotovelos empurrando para baixo.'),
('d603bd2f-356a-4079-b5db-147dffb9901b', 'Extensão de Punho', 'FOREARMS', 'Sentado, apoie o antebraço na coxa e estenda o punho segurando a barra ou halter.'),
('bc530fd6-f5a9-409c-9be3-0cf6a9fd3fa8', 'Caminhada do Fazendeiro', 'FOREARMS', 'Segurando halteres pesados ao lado do corpo, caminhe mantendo a postura ereta.'),
('fb90eaa1-089c-4f28-8bde-d811c76adb89', 'Extensor de Antebraço com Elástico', 'FOREARMS', 'Com o elástico preso, estenda os dedos contra a resistência.'),
('04228ab0-edf4-4838-b045-5dfc36b66115', 'Abdominal Bicicleta', 'ABDOMINALS', 'Deitado, alterne cotovelo e joelho opostos em movimento de pedalada.'),
('bacf392c-3384-42b8-82fd-763fd7c45d50', 'Abdominal Oblíquo', 'ABDOMINALS', 'Deitado, flexione o tronco em direção lateral contraindo o oblíquo.'),
('67936659-7226-40b7-8634-abee42648a22', 'Prancha Lateral', 'ABDOMINALS', 'Apoiado em um antebraço e na lateral dos pés, mantenha o corpo alinhado e estático.'),
('e8f54a11-bf00-4fc2-af70-f16464fcabcd', 'Elevação de Pernas na Barra', 'ABDOMINALS', 'Pendurado na barra, eleve as pernas estendidas até a altura do quadril.'),
('af797999-0f58-4b45-afce-3b841dd4e6d0', 'Afundo', 'QUADRICEPS', 'Dê um passo à frente e flexione ambos os joelhos até formarem ângulos de 90 graus.'),
('f8640022-4316-4fbb-ae44-a61b6642468f', 'Agachamento Búlgaro', 'QUADRICEPS', 'Com um pé apoiado atrás em um banco, flexione o joelho da perna da frente.'),
('b1ce3bbc-7688-4b3e-9e6b-c0c3df7e81c6', 'Agachamento Frontal', 'QUADRICEPS', 'Com a barra apoiada à frente dos ombros, flexione os joelhos descendo o quadril.'),
('441d65c7-c891-4d21-b29b-26fbeabe9025', 'Hack Squat', 'QUADRICEPS', 'No aparelho, com as costas apoiadas, flexione os joelhos empurrando a plataforma.'),
('91ce7456-5415-4eb8-8eb1-4247916a6fd1', 'Flexora Unilateral', 'HAMSTRINGS', 'No aparelho, flexione uma perna de cada vez trazendo o peso em direção ao glúteo.'),
('528efc8e-3e1f-4fb8-a0bb-5a08e070e369', 'Mesa Flexora', 'HAMSTRINGS', 'Deitado de bruços no aparelho, flexione os joelhos trazendo o peso em direção ao glúteo.'),
('9af30ddf-d1e4-472f-82c1-228f4ae500d3', 'Agachamento Sumô', 'GLUTES', 'Com as pernas afastadas e pés apontados para fora, flexione os joelhos e retorne.'),
('065150cd-97b1-42a4-9cab-8c083a53b00d', 'Abdução de Quadril em Pé', 'GLUTES', 'Em pé, com apoio, afaste a perna lateralmente contraindo o glúteo.'),
('a08a2e70-0e3d-4cff-a309-68313f411b71', 'Elevação Pélvica Unilateral', 'GLUTES', 'Deitado, com uma perna apoiada, eleve o quadril contraindo o glúteo de um lado por vez.'),
('a61777c3-7db9-494e-ac55-7f3200ab82c2', 'Glúteo na Polia (Quatro Apoios)', 'GLUTES', 'Apoiado de quatro, estenda a perna para cima contra a resistência do cabo.'),
('f786f9c7-92f4-498c-b288-99d3efffc31d', 'Abdução no Cabo', 'ABDUCTORS', 'Em pé, com o cabo preso ao tornozelo, afaste a perna lateralmente do corpo.'),
('20d55a30-bafd-49c3-87a0-fcd59c733c11', 'Adução no Cabo', 'ADDUCTORS', 'Em pé, com o cabo preso ao tornozelo, aproxime a perna em direção ao centro do corpo.'),
('36dd4cb8-9869-47a7-a243-debab135ac9b', 'Panturrilha no Leg Press', 'CALVES', 'No leg press, empurre a plataforma usando apenas a ponta dos pés.'),
('6e72b2a6-0ec0-41ad-919b-a0c03b5a48fe', 'Panturrilha Burrinho', 'CALVES', 'Inclinado à frente com peso nas costas, eleve os calcanhares ficando na ponta dos pés.'),
('04c754b7-a48a-406c-b22d-b77ae69d8e8c', 'Flexão Lateral de Pescoço', 'NECK', 'Sentado ou em pé, incline a cabeça lateralmente resistindo levemente ao movimento.'),
('010d1186-f962-44cd-99b1-8fb9979f3b13', 'Encolhimento de Pescoço', 'NECK', 'Deitado, eleve levemente a cabeça contraindo a musculatura anterior do pescoço.')
